#[derive(Parser, Debug)]
#[command(name = "dust")]
#[command(version = "1.2.3")]
#[command(about = "Like du but more intuitive", long_about = None)]
struct Args {
    /// Input files or directories
    #[arg(value_name = "PATH")]
    paths: Vec<PathBuf>,

    /// Depth to show
    #[arg(short, long)]
    depth: Option<usize>,

    /// Number of threads to use
