    #[arg(long)]
    config: Option<PathBuf>,

    /// Number of lines of output to show. (Default is terminal_height - 10)
    #[arg(short, long)]
    number_of_lines: Option<usize>,

    /// Subdirectories will not have their path shortened
    #[arg(short, long)]
    full_paths: bool,

    /// Exclude any file or directory with this path
    #[arg(short, long)]
    ignore_directory: Vec<String>,

    /// Exclude any file or directory with a regex matching that listed in this file
    #[arg(short, long)]
    ignore_all_in_file: Option<PathBuf>,

    /// dereference sym links - Treat sym links as directories and go into them
    #[arg(short = 'L', long)]
    dereference_links: bool,

    /// Only count the files and directories on the same filesystem as the supplied directory
    #[arg(short, long)]
    limit_filesystem: bool,

    /// Use file length instead of blocks
    #[arg(short, long)]
    apparent_size: bool,

    /// Print tree upside down (biggest highest)
    #[arg(short, long)]
    reverse: bool,

    /// No colors will be printed (Useful for commands like: watch)
    #[arg(short, long)]
    no_colors: bool,

    /// Force colors print
    #[arg(short = 'C', long)]
    force_colors: bool,

    /// No percent bars or percentages will be displayed
    #[arg(short, long)]
    no_percent_bars: bool,

    /// percent bars moved to right side of screen
    #[arg(short = 'B', long)]
    bars_on_right: bool,

    /// Minimum size file to include in output
    #[arg(short, long)]
    min_size: Option<String>,

    /// For screen readers. Removes bars. Adds new column: depth level
    #[arg(short = 'R', long)]
    screen_reader: bool,

    /// No total row will be displayed
    #[arg(long)]
    skip_total: bool,

    /// Directory 'size' is number of child files instead of disk size
    #[arg(short, long)]
    filecount: bool,

    /// Do not display hidden files
    #[arg(short, long)]
    ignore_hidden: bool,

    /// Exclude filepaths matching this regex
    #[arg(short, long)]
    invert_filter: Option<String>,

    /// Only include filepaths matching this regex
    #[arg(short, long)]
    filter: Option<String>,

    /// show only these file types
    #[arg(short, long)]
    file_types: bool,

    /// Specify width of output overriding the auto detection of terminal width
    #[arg(short, long)]
    terminal_width: Option<usize>,

    /// Disable the progress indication
    #[arg(short = 'P', long)]
    no_progress: bool,

    /// Print path with errors
    #[arg(long)]
    print_errors: bool,

    /// Only directories will be displayed
    #[arg(short = 'D', long)]
    only_dir: bool,

    /// Only files will be displayed. (Finds your largest files)
    #[arg(short = 'F', long)]
    only_file: bool,

    /// Changes output display size
    #[arg(short, long)]
    output_format: Option<String>,

    /// Specify memory to use as stack size
    #[arg(short = 'S', long)]
    stack_size: Option<String>,

    /// Output the directory tree as json to the current directory
    #[arg(short, long)]
    output_json: bool,

    /// +/-n matches files modified more/less than n days ago
    #[arg(short = 'M', long)]
    mtime: Option<String>,

    /// just like -mtime, but based on file access time
    #[arg(short = 'A', long)]
    atime: Option<String>,

    /// just like -mtime, but based on file change time
    #[arg(short, long)]
    ctime: Option<String>,

    /// Read NUL-terminated paths from FILE (use `-` for stdin)
    #[arg(long)]
    files0_from: Option<PathBuf>,

    /// Read newline-terminated paths from FILE (use `-` for stdin)
    #[arg(long)]
    files_from: Option<PathBuf>,

    /// Keep these directories collapsed
    #[arg(long)]
    collapse: Option<String>,

    /// Directory 'size' is max filetime of child files instead of disk size
    #[arg(short, long)]
    filetime: Option<String>,
}

fn main() {
    let mut args = Args::parse();

    // Load config file if exists
    if let Some(config_path) = &args.config {
        if let Ok(config) = config::load_config(config_path) {
            args.merge_config(config);
        }
    } else {
        // Try default config locations
