    no_percent_bars: bool,

    /// percent bars moved to right side of screen
    #[arg(short = 'B', long)]
    bars_on_right: bool,

    /// Minimum size file to include in output
    #[arg(short, long)]
    min_size: Option<String>,

    /// For screen readers. Removes bars. Adds new column: depth level
    #[arg(short = 'R', long)]
    screen_reader: bool,

    /// No total row will be displayed
    #[arg(long)]
    skip_total: bool,

    /// Directory 'size' is number of child files instead of disk size
    #[arg(short, long)]
    filecount: bool,

    /// Do not display hidden files
    #[arg(short, long)]
    ignore_hidden: bool,

    /// Exclude filepaths matching this regex
    #[arg(short, long)]
    invert_filter: Option<String>,

    /// Only include filepaths matching this regex
    #[arg(short, long)]
    filter: Option<String>,

    /// show only these file types
    #[arg(short, long)]
    file_types: bool,

    /// Specify width of output overriding the auto detection of terminal width
    #[arg(short, long)]
    terminal_width: Option<usize>,

    /// Disable the progress indication
    #[arg(short = 'P', long)]
    no_progress: bool,

    /// Print path with errors
    #[arg(long)]
    print_errors: bool,

    /// Only directories will be displayed
    #[arg(short = 'D', long)]
    only_dir: bool,

    /// Only files will be displayed. (Finds your largest files)
    #[arg(short = 'F', long)]
    only_file: bool,

    /// Changes output display size
    #[arg(short, long)]
    output_format: Option<String>,

    /// Specify memory to use as stack size
    #[arg(short = 'S', long)]
    stack_size: Option<String>,

    /// Output the directory tree as json to the current directory
    #[arg(short, long)]
    output_json: bool,

    /// +/-n matches files modified more/less than n days ago
    #[arg(short = 'M', long)]
    mtime: Option<String>,

    /// just like -mtime, but based on file access time
    #[arg(short = 'A', long)]
    atime: Option<String>,

    /// just like -mtime, but based on file change time
    #[arg(short, long)]
    ctime: Option<String>,

    /// Read NUL-terminated paths from FILE (use `-` for stdin)
    #[arg(long)]
    files0_from: Option<PathBuf>,

    /// Read newline-terminated paths from FILE (use `-` for stdin)
    #[arg(long)]
    files_from: Option<PathBuf>,

    /// Keep these directories collapsed
    #[arg(long)]
    collapse: Option<String>,

    /// Directory 'size' is max filetime of child files instead of disk size
    #[arg(short, long)]
    filetime: Option<String>,
}

fn main() {
    let mut args = Args::parse();

    // Load config file if exists
    if let Some(config_path) = &args.config {
        if let Ok(config) = config::load_config(config_path) {
            args.merge_config(config);
        }
    } else {
        // Try default config locations
        if let Some(home) = dirs::home_dir() {
            let config_paths = [
                home.join(".config/dust/config.toml"),
                home.join(".dust.toml"),
            ];
            for config_path in &config_paths {
                if config_path.exists() {
                    if let Ok(config) = config::load_config(config_path) {
                        args.merge_config(config);
                        break;
                    }
                }
            }
        }
    }

    // Default path is current directory
    if args.paths.is_empty() {
        args.paths.push(PathBuf::from("."));
    }

    // Build the tree
    let mut total_size = 0u64;
    let mut all_nodes = Vec::new();

    for path in &args.paths {
        if let Ok(nodes) = tree::scan_dir(path, &args, 0) {
            for node in nodes {
                total_size += node.size;
                all_nodes.push(node);
            }
        }
    }

    // Format and display
    let formatter = TreeFormatter::new(&args);
    formatter.display(&all_nodes, total_size);
}

impl Args {
    fn merge_config(&mut self, config: config::Config) {
        // Merge config file settings (config overrides defaults but not CLI args)
        if !self.no_colors && config.no_colors.unwrap_or(false) {
            self.no_colors = true;
        }
        if !self.reverse && config.reverse.unwrap_or(false) {
            self.reverse = true;
        }
        if self.depth.is_none() {
            self.depth = config.depth;
        }
        if self.number_of_lines.is_none() {
            self.number_of_lines = config.number_of_lines;
        }
        if !self.full_paths && config.display_full_paths.unwrap_or(false) {
            self.full_paths = true;
        }
        if !self.apparent_size && config.display_apparent_size.unwrap_or(false) {
            self.apparent_size = true;
        }
        if !self.no_percent_bars && config.no_bars.unwrap_or(false) {
            self.no_percent_bars = true;
        }
        if !self.skip_total && config.skip_total.unwrap_or(false) {
            self.skip_total = true;
        }
        if !self.ignore_hidden && config.ignore_hidden.unwrap_or(false) {
            self.ignore_hidden = true;
        }
        if self.output_format.is_none() {
            self.output_format = config.output_format;
        }
    }
}

mod dirs {
    use std::path::PathBuf;
    pub fn home_dir() -> Option<PathBuf> {
        std::env::var_os("HOME").map(PathBuf::from)
    }
}
