use std::path::{Path, PathBuf};
use std::fs;
use std::os::unix::fs::MetadataExt;
use regex::Regex;

#[derive(Debug, Clone)]
pub enum NodeType {
    File,
    Directory,
}

#[derive(Debug, Clone)]
pub struct FileNode {
    pub path: PathBuf,
    pub name: String,
    pub size: u64,
    pub node_type: NodeType,
    pub depth: usize,
    pub file_count: usize,
}

pub fn scan_dir(path: &Path, args: &crate::Args, depth: usize) -> Result<Vec<FileNode>, Box<dyn std::error::Error>> {
    let mut nodes = Vec::new();

    if let Ok(metadata) = fs::metadata(path) {
        let size = if args.apparent_size {
            metadata.len()
        } else {
            metadata.blocks() * 512
        };

        let name = path.file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("?")
            .to_string();

        let node = FileNode {
            path: path.to_path_buf(),
            name,
            size,
            node_type: if metadata.is_dir() { NodeType::Directory } else { NodeType::File },
            depth,
            file_count: 0,
        };

        nodes.push(node);

        if metadata.is_dir() && (args.depth.is_none() || depth < args.depth.unwrap()) {
            if let Ok(entries) = fs::read_dir(path) {
                for entry in entries {
                    if let Ok(entry) = entry {
                        if let Ok(child_nodes) = scan_dir(&entry.path(), args, depth + 1) {
                            nodes.extend(child_nodes);
                        }
                    }
                }
            }
        }
    }

    Ok(nodes)
}
