        Args {
            paths: Vec::new(),
            depth: None,
            threads: None,
            config: None,
            number_of_lines: None,
            full_paths: false,
            ignore_directory: Vec::new(),
            ignore_all_in_file: None,
            dereference_links: false,
            limit_filesystem: false,
            apparent_size: false,
            reverse: false,
            no_colors: false,
            force_colors: false,
            no_percent_bars: false,
            bars_on_right: false,
            min_size: None,
            screen_reader: false,
            skip_total: false,
            filecount: false,
            ignore_hidden: false,
            invert_filter: None,
            filter: None,
            file_types: false,
            terminal_width: None,
            no_progress: false,
            print_errors: false,
            only_dir: false,
            only_file: false,
            output_format: None,
            stack_size: None,
