        // Merge config file settings (config overrides defaults but not CLI args)
        if !self.no_colors && config.no_colors.unwrap_or(false) {
            self.no_colors = true;
        }
        if !self.reverse && config.reverse.unwrap_or(false) {
            self.reverse = true;
        }
        if self.depth.is_none() {
            self.depth = config.depth;
        }
        if self.number_of_lines.is_none() {
            self.number_of_lines = config.number_of_lines;
        }
        if !self.full_paths && config.display_full_paths.unwrap_or(false) {
            self.full_paths = true;
        }
        if !self.apparent_size && config.display_apparent_size.unwrap_or(false) {
            self.apparent_size = true;
        }
        if !self.no_percent_bars && config.no_bars.unwrap_or(false) {
            self.no_percent_bars = true;
        }
        if !self.skip_total && config.skip_total.unwrap_or(false) {
            self.skip_total = true;
        }
        if !self.ignore_hidden && config.ignore_hidden.unwrap_or(false) {
            self.ignore_hidden = true;
        }
        if self.output_format.is_none() {
            self.output_format = config.output_format;
        }
    }
}
