use std::fs;
use crate::Args;

#[derive(Debug, Clone)]
pub struct FileNode {
    pub path: PathBuf,
    pub name: String,
    pub size: u64,
    pub is_dir: bool,
    pub depth: usize,
}

pub fn scan_dir(path: &Path, args: &Args, depth: usize) -> Result<Vec<FileNode>, Box<dyn std::error::Error>> {
    let mut nodes = Vec::new();

    if let Ok(metadata) = fs::metadata(path) {
        let size = if args.apparent_size {
            metadata.len()
        } else {
            // Use st_blocks * 512 for block size
            #[cfg(unix)]
            {
                use std::os::unix::fs::MetadataExt;
                metadata.blocks() * 512
            }
            #[cfg(not(unix))]
            {
                metadata.len()
            }
        };

        let name = path.file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("?")
            .to_string();

        let is_dir = metadata.is_dir();

        // Check if hidden and should be ignored
        if args.ignore_hidden && name.starts_with('.') {
            return Ok(nodes);
        }

        // Check filter and invert_filter
        let path_str = path.to_string_lossy();
        if let Some(ref filter) = args.filter {
            // Simple glob matching
            if !simple_match(&path_str, filter) {
                return Ok(nodes);
            }
        }
        if let Some(ref invert) = args.invert_filter {
            if simple_match(&path_str, invert) {
                return Ok(nodes);
            }
        }

        let node = FileNode {
            path: path.to_path_buf(),
            name,
            size,
            is_dir,
            depth,
        };

        nodes.push(node);

        if is_dir && (args.depth.is_none() || depth < args.depth.unwrap()) {
            if let Ok(entries) = fs::read_dir(path) {
                for entry in entries.flatten() {
                    if let Ok(mut child_nodes) = scan_dir(&entry.path(), args, depth + 1) {
                        nodes.append(&mut child_nodes);
                    }
                }
            }
        }
    }

    Ok(nodes)
}

fn simple_match(text: &str, pattern: &str) -> bool {
    // Very simple pattern matching for regex-like patterns
    if pattern.is_empty() {
        return true;
    }

    // Handle simple suffix matching like "\.png$"
    if pattern.ends_with('$') {
        let pattern = &pattern[..pattern.len()-1];
        text.ends_with(pattern)
    } else {
        text.contains(pattern)
    }
}
