}

pub fn load_config(path: &Path) -> Result<Config, Box<dyn std::error::Error>> {
    let content = fs::read_to_string(path)?;
    parse_toml(&content)
}

fn parse_toml(content: &str) -> Result<Config, Box<dyn std::error::Error>> {
    let mut config = Config::default();

    for line in content.lines() {
        let line = line.trim();

        // Skip comments and empty lines
        if line.is_empty() || line.starts_with('#') {
            continue;
        }

        if line.starts_with("reverse") {
            config.reverse = parse_bool_value(line);
        } else if line.starts_with("display-full-paths") {
            config.display_full_paths = parse_bool_value(line);
        } else if line.starts_with("display-apparent-size") {
            config.display_apparent_size = parse_bool_value(line);
        } else if line.starts_with("no-colors") {
            config.no_colors = parse_bool_value(line);
        } else if line.starts_with("no-bars") {
            config.no_bars = parse_bool_value(line);
        } else if line.starts_with("skip-total") {
            config.skip_total = parse_bool_value(line);
        } else if line.starts_with("ignore-hidden") {
            config.ignore_hidden = parse_bool_value(line);
        } else if line.starts_with("output-format") {
            config.output_format = parse_string_value(line);
        } else if line.starts_with("number-of-lines") {
            config.number_of_lines = parse_int_value(line);
        } else if line.starts_with("depth") {
            config.depth = parse_int_value(line);
        }
    }

    Ok(config)
}

fn parse_bool_value(line: &str) -> Option<bool> {
    if let Some(eq_pos) = line.find('=') {
        let value = line[eq_pos+1..].trim();
        if value == "true" {
            Some(true)
        } else if value == "false" {
            Some(false)
        } else {
            None
        }
    } else {
        None
    }
}

fn parse_string_value(line: &str) -> Option<String> {
    if let Some(eq_pos) = line.find('=') {
        let value = line[eq_pos+1..].trim();
        // Remove quotes
        let value = if (value.starts_with('"') && value.ends_with('"')) 
            || (value.starts_with('\'') && value.ends_with('\'')) {
            &value[1..value.len()-1]
        } else {
            value
        };
        Some(value.to_string())
    } else {
        None
    }
}

fn parse_int_value(line: &str) -> Option<usize> {
    if let Some(eq_pos) = line.find('=') {
        let value = line[eq_pos+1..].trim();
        value.parse().ok()
    } else {
        None
    }
}
