use std::path::{Path, PathBuf};
use std::fs;
use std::collections::{BTreeMap, HashMap};
use crate::Args;

#[derive(Debug, Clone)]
pub struct FileNode {
    pub path: PathBuf,
    pub name: String,
    pub size: u64,
    pub is_dir: bool,
    pub depth: usize,
    pub children: Vec<FileNode>,
}

pub fn scan_dir(path: &Path, args: &Args, depth: usize) -> Result<Vec<FileNode>, Box<dyn std::error::Error>> {
    let mut nodes = Vec::new();

    if let Ok(metadata) = fs::metadata(path) {
        let name = path.file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("?")
            .to_string();

        // Check if hidden and should be ignored
        if args.ignore_hidden && name.starts_with('.') {
            return Ok(nodes);
        }

        // Check filter and invert_filter
        let path_str = path.to_string_lossy();
        if let Some(ref filter) = args.filter {
            if !simple_match(&path_str, filter) {
                return Ok(nodes);
            }
        }
        if let Some(ref invert) = args.invert_filter {
            if simple_match(&path_str, invert) {
                return Ok(nodes);
            }
        }

        let is_dir = metadata.is_dir();
        let size = if args.apparent_size {
            metadata.len()
        } else {
            #[cfg(unix)]
            {
                use std::os::unix::fs::MetadataExt;
                metadata.blocks() * 512
            }
            #[cfg(not(unix))]
            {
                metadata.len()
            }
        };

        let mut node = FileNode {
            path: path.to_path_buf(),
            name,
            size,
            is_dir,
            depth,
            children: Vec::new(),
        };

        if is_dir && (args.depth.is_none() || depth < args.depth.unwrap()) {
            if let Ok(entries) = fs::read_dir(path) {
                for entry in entries.flatten() {
                    if let Ok(child_nodes) = scan_dir(&entry.path(), args, depth + 1) {
                        node.children.extend(child_nodes);
                    }
                }
            }
        }

        nodes.push(node);
    }

    Ok(nodes)
}

pub fn aggregate_tree(nodes: Vec<FileNode>, args: &Args) -> Vec<FileNode> {
    // Flatten the tree and aggregate
    let mut result = Vec::new();
    for node in nodes {
        collect_nodes(&node, &mut result, args);
    }
    result
}

fn collect_nodes(node: &FileNode, result: &mut Vec<FileNode>, args: &Args) {
    let mut current = node.clone();
    current.children.clear();

    // Add this node
    result.push(current);

    // Recursively add children
    for child in &node.children {
        collect_nodes(child, result, args);
    }
}

fn simple_match(text: &str, pattern: &str) -> bool {
    if pattern.is_empty() {
        return true;
    }

    if pattern.ends_with('$') {
        let pattern = &pattern[..pattern.len()-1];
        text.ends_with(pattern)
    } else {
        text.contains(pattern)
    }
}
