use std::path::{Path, PathBuf};
use std::fs;
use std::collections::HashMap;
use crate::Args;

#[derive(Debug, Clone)]
pub struct FileNode {
    pub path: PathBuf,
    pub name: String,
    pub size: u64,
    pub is_dir: bool,
    pub depth: usize,
    pub parent_path: Option<PathBuf>,
}

pub fn scan_dir(path: &Path, args: &Args, depth: usize) -> Result<Vec<FileNode>, Box<dyn std::error::Error>> {
    let mut nodes = Vec::new();

    scan_dir_recursive(path, args, depth, None, &mut nodes)?;

    Ok(nodes)
}

fn scan_dir_recursive(path: &Path, args: &Args, depth: usize, parent_path: Option<PathBuf>, nodes: &mut Vec<FileNode>) -> Result<(), Box<dyn std::error::Error>> {
    if let Ok(metadata) = fs::metadata(path) {
        let name = path.file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("?")
            .to_string();

        // Check if hidden and should be ignored
        if args.ignore_hidden && name.starts_with('.') {
            return Ok(());
        }

        // Check filter and invert_filter
        let path_str = path.to_string_lossy();
        if let Some(ref filter) = args.filter {
            if !simple_match(&path_str, filter) {
                return Ok(());
            }
        }
        if let Some(ref invert) = args.invert_filter {
            if simple_match(&path_str, invert) {
                return Ok(());
            }
        }

        let is_dir = metadata.is_dir();
        let size = if args.apparent_size {
            metadata.len()
        } else {
            #[cfg(unix)]
            {
                use std::os::unix::fs::MetadataExt;
                metadata.blocks() * 512
            }
            #[cfg(not(unix))]
            {
                metadata.len()
            }
        };

        let node = FileNode {
            path: path.to_path_buf(),
            name,
            size,
            is_dir,
            depth,
            parent_path: parent_path.clone(),
        };

        nodes.push(node);

        if is_dir && (args.depth.is_none() || depth < args.depth.unwrap()) {
            if let Ok(entries) = fs::read_dir(path) {
                for entry in entries.flatten() {
                    scan_dir_recursive(&entry.path(), args, depth + 1, Some(path.to_path_buf()), nodes)?;
                }
            }
        }
    }

    Ok(())
}

pub fn aggregate_tree(mut nodes: Vec<FileNode>, args: &Args) -> Vec<FileNode> {
    // Calculate directory sizes as sum of their children
    let mut dir_sizes: HashMap<PathBuf, u64> = HashMap::new();

    // First pass: collect all directory sums
    for node in &nodes {
        if let Some(ref parent) = node.parent_path {
            *dir_sizes.entry(parent.clone()).or_insert(0) += node.size;
        }
    }

    // Second pass: update directory node sizes and collect results
    for node in &mut nodes {
        if node.is_dir {
            if let Some(&total) = dir_sizes.get(&node.path) {
                node.size = total;
            }
        }
    }

    // Sort by depth first, then by size
    nodes.sort_by(|a, b| {
        let depth_cmp = a.depth.cmp(&b.depth);
        if depth_cmp == std::cmp::Ordering::Equal {
            if args.reverse {
                a.size.cmp(&b.size)
            } else {
                b.size.cmp(&a.size)
            }
        } else {
            depth_cmp
        }
    });

    // Filter by only_dir or only_file
    nodes.retain(|n| {
        if args.only_dir {
            n.is_dir
        } else if args.only_file {
            !n.is_dir
        } else {
            true
        }
    });

    nodes
}

fn simple_match(text: &str, pattern: &str) -> bool {
    if pattern.is_empty() {
        return true;
    }

    if pattern.ends_with('$') {
        let pattern = &pattern[..pattern.len()-1];
        text.ends_with(pattern)
    } else {
        text.contains(pattern)
    }
}
