mod parser;
mod tree;
mod formatter;
mod config;

use formatter::TreeFormatter;

#[derive(Debug, Clone)]
pub struct Args {
    pub paths: Vec<PathBuf>,
    pub depth: Option<usize>,
    pub threads: Option<usize>,
    pub config: Option<PathBuf>,
    pub number_of_lines: Option<usize>,
    pub full_paths: bool,
    pub ignore_directory: Vec<String>,
    pub ignore_all_in_file: Option<PathBuf>,
    pub dereference_links: bool,
    pub limit_filesystem: bool,
    pub apparent_size: bool,
    pub reverse: bool,
    pub no_colors: bool,
    pub force_colors: bool,
    pub no_percent_bars: bool,
    pub bars_on_right: bool,
    pub min_size: Option<String>,
    pub screen_reader: bool,
    pub skip_total: bool,
    pub filecount: bool,
    pub ignore_hidden: bool,
    pub invert_filter: Option<String>,
    pub filter: Option<String>,
    pub file_types: bool,
    pub terminal_width: Option<usize>,
    pub no_progress: bool,
    pub print_errors: bool,
    pub only_dir: bool,
    pub only_file: bool,
    pub output_format: Option<String>,
    pub stack_size: Option<String>,
    pub output_json: bool,
    pub mtime: Option<String>,
    pub atime: Option<String>,
    pub ctime: Option<String>,
    pub files0_from: Option<PathBuf>,
    pub files_from: Option<PathBuf>,
    pub collapse: Option<String>,
    pub filetime: Option<String>,
}

impl Default for Args {
    fn default() -> Self {
        Args {
            paths: Vec::new(),
            depth: None,
            threads: None,
            config: None,
            number_of_lines: None,
            full_paths: false,
            ignore_directory: Vec::new(),
            ignore_all_in_file: None,
            dereference_links: false,
            limit_filesystem: false,
            apparent_size: false,
            reverse: false,
            no_colors: false,
            force_colors: false,
            no_percent_bars: false,
            bars_on_right: false,
            min_size: None,
            screen_reader: false,
            skip_total: false,
            filecount: false,
            ignore_hidden: false,
            invert_filter: None,
            filter: None,
            file_types: false,
            terminal_width: None,
            no_progress: false,
            print_errors: false,
            only_dir: false,
            only_file: false,
            output_format: None,
            stack_size: None,
            output_json: false,
            mtime: None,
            atime: None,
            ctime: None,
            files0_from: None,
            files_from: None,
            collapse: None,
            filetime: None,
        }
    }
}

fn main() {
    let mut args = parser::parse_args();

    // Load config file if exists
    if let Some(config_path) = &args.config {
        if let Ok(cfg) = config::load_config(config_path) {
            args.merge_config(cfg);
        }
    } else {
        // Try default config locations
        if let Some(home) = home_dir() {
            let config_paths = [
                home.join(".config/dust/config.toml"),
                home.join(".dust.toml"),
            ];
            for config_path in &config_paths {
                if config_path.exists() {
                    if let Ok(cfg) = config::load_config(config_path) {
                        args.merge_config(cfg);
                        break;
                    }
                }
            }
        }
    }

    // Default path is current directory
    if args.paths.is_empty() {
        args.paths.push(PathBuf::from("."));
    }

    // Build the tree
    let mut all_nodes = Vec::new();

    // Show progress
    if !args.no_progress {
        eprint!("\r\n \nIndexing:  0 files, 0B ... -\r\n                            \r");
    }

    for path in &args.paths {
        if let Ok(nodes) = tree::scan_dir(path, &args, 0) {
            all_nodes.extend(nodes);
        }
    }

    // Clear progress line
    if !args.no_progress {
        eprint!("\r                            \r");
    }

    // Aggregate sizes
    let aggregated = tree::aggregate_tree(all_nodes, &args);
    let total_size: u64 = aggregated.iter()
        .filter(|n| n.depth == 0)
        .map(|n| n.size)
        .sum();

    // Format and display
    let formatter = TreeFormatter::new(&args);
    formatter.display(&aggregated, total_size);
}

fn home_dir() -> Option<PathBuf> {
    env::var_os("HOME").map(PathBuf::from)
}

impl Args {
    fn merge_config(&mut self, config: config::Config) {
        // Merge config file settings
        if !self.no_colors && config.no_colors.unwrap_or(false) {
            self.no_colors = true;
        }
        if !self.reverse && config.reverse.unwrap_or(false) {
            self.reverse = true;
        }
        if self.depth.is_none() {
            self.depth = config.depth;
        }
        if self.number_of_lines.is_none() {
            self.number_of_lines = config.number_of_lines;
        }
        if !self.full_paths && config.display_full_paths.unwrap_or(false) {
            self.full_paths = true;
        }
        if !self.apparent_size && config.display_apparent_size.unwrap_or(false) {
            self.apparent_size = true;
        }
        if !self.no_percent_bars && config.no_bars.unwrap_or(false) {
            self.no_percent_bars = true;
        }
        if !self.skip_total && config.skip_total.unwrap_or(false) {
            self.skip_total = true;
        }
        if !self.ignore_hidden && config.ignore_hidden.unwrap_or(false) {
            self.ignore_hidden = true;
        }
        if self.output_format.is_none() {
            self.output_format = config.output_format;
        }
    }
}
