use std::fs;
use std::collections::HashMap;
use crate::Args;

#[derive(Debug, Clone)]
pub struct FileNode {
    pub path: PathBuf,
    pub name: String,
    pub size: u64,
    pub is_dir: bool,
    pub depth: usize,
}

pub fn scan_dir(start_path: &Path, args: &Args, _depth: usize) -> Result<Vec<FileNode>, Box<dyn std::error::Error>> {
    let mut all_files = Vec::new();
    scan_recursive(start_path, args, 0, &mut all_files)?;
    Ok(all_files)
}

fn scan_recursive(path: &Path, args: &Args, depth: usize, all_files: &mut Vec<FileNode>) -> Result<(), Box<dyn std::error::Error>> {
    let metadata = fs::metadata(path)?;

    let name = path.file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("?")
        .to_string();

    // Check if hidden and should be ignored
    if args.ignore_hidden && name.starts_with('.') {
        return Ok(());
    }

    let is_dir = metadata.is_dir();
    let file_size = if args.apparent_size {
        metadata.len()
    } else {
        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt;
            metadata.blocks() * 512
        }
        #[cfg(not(unix))]
        {
            metadata.len()
        }
    };

    all_files.push(FileNode {
        path: path.to_path_buf(),
        name,
        size: file_size,
        is_dir,
        depth,
    });

    // Recurse into directories
    if is_dir && (args.depth.is_none() || depth < args.depth.unwrap()) {
        if let Ok(entries) = fs::read_dir(path) {
            for entry in entries.flatten() {
                scan_recursive(&entry.path(), args, depth + 1, all_files)?;
            }
        }
    }

    Ok(())
}

pub fn aggregate_tree(mut nodes: Vec<FileNode>, args: &Args) -> Vec<FileNode> {
    // Calculate cumulative size for each directory
    let mut dir_sizes: HashMap<PathBuf, u64> = HashMap::new();

    // For each file, add its size to all parent directories
    for node in &nodes {
        if !node.is_dir {
            // Add to immediate parent
            if let Some(parent) = node.path.parent() {
                *dir_sizes.entry(parent.to_path_buf()).or_insert(0) += node.size;
            }
        }
    }

    // Update directory sizes
    for node in &mut nodes {
        if node.is_dir {
            if let Some(&total) = dir_sizes.get(&node.path) {
                node.size = total;
            }
        }
    }

    // Sort by depth, then by size (reverse if flag set)
    nodes.sort_by(|a, b| {
        match a.depth.cmp(&b.depth) {
            std::cmp::Ordering::Equal => {
                if args.reverse {
                    a.size.cmp(&b.size)
                } else {
                    b.size.cmp(&a.size)
                }
            }
            other => other,
        }
    });

    // Filter by file/dir type
    if args.only_dir {
        nodes.retain(|n| n.is_dir);
    } else if args.only_file {
        nodes.retain(|n| !n.is_dir);
    }

    nodes
}

fn simple_match(text: &str, pattern: &str) -> bool {
    if pattern.is_empty() {
        return true;
    }

    if pattern.ends_with('$') {
        let pattern = &pattern[..pattern.len()-1];
        text.ends_with(pattern)
    } else {
        text.contains(pattern)
    }
}
