use crate::{Args, tree::FileNode};
use std::collections::{HashMap, VecDeque};
use std::path::PathBuf;

pub struct TreeFormatter<'a> {
    args: &'a Args,
}

impl<'a> TreeFormatter<'a> {
    pub fn new(args: &'a Args) -> Self {
        TreeFormatter { args }
    }

    pub fn display(&self, nodes: &[FileNode], total_size: u64) {
        // Group by parent directory
        let mut by_parent: HashMap<Option<PathBuf>, Vec<&FileNode>> = HashMap::new();

        for node in nodes {
            let parent = node.path.parent().map(|p| p.to_path_buf());
            by_parent.entry(parent).or_insert_with(Vec::new).push(node);
        }

        // Sort within each parent
        for children in by_parent.values_mut() {
            children.sort_by(|a, b| {
                if self.args.reverse {
                    a.size.cmp(&b.size)
                } else {
                    b.size.cmp(&a.size)
                }
            });
        }

        // Print in depth-first order
        self.print_tree(&by_parent, nodes, total_size);

        // Print total
        if !self.args.skip_total {
            self.print_total(total_size);
        }
    }

    fn print_tree(&self, by_parent: &HashMap<Option<PathBuf>, Vec<&FileNode>>, all_nodes: &[FileNode], total_size: u64) {
        // Find the root nodes (depth 0)
        for node in all_nodes {
            if node.depth == 0 {
                self.print_subtree(node, by_parent, all_nodes, total_size, true);
            }
        }
    }

    fn print_subtree(&self, node: &FileNode, by_parent: &HashMap<Option<PathBuf>, Vec<&FileNode>>, all_nodes: &[FileNode], total_size: u64, is_root: bool) {
        if node.is_dir {
            // Print children first
            let parent_key = Some(node.path.clone());
            if let Some(children) = by_parent.get(&parent_key) {
                for child in children {
                    self.print_node(child, total_size);
                }
            }
        }

        // Then print the directory itself
        if is_root && node.depth == 0 {
            // For root, use ┌─┴
            self.print_node_with_connector(node, total_size, "┌─┴ ");
        } else if node.is_dir && node.depth > 0 {
            // For subdirectories, use ├─┴
            self.print_node_with_connector(node, total_size, "├─┴ ");
