use std::path::{Path, PathBuf};
use std::fs;
use std::collections::HashMap;
use crate::Args;

#[derive(Debug, Clone)]
pub struct FileNode {
    pub path: PathBuf,
    pub name: String,
    pub size: u64,
    pub is_dir: bool,
    pub depth: usize,
}

pub fn scan_dir(start_path: &Path, args: &Args, _depth: usize) -> Result<Vec<FileNode>, Box<dyn std::error::Error>> {
    let mut all_files = Vec::new();
    scan_recursive(start_path, args, 0, &mut all_files)?;
    Ok(all_files)
}

fn scan_recursive(path: &Path, args: &Args, depth: usize, all_files: &mut Vec<FileNode>) -> Result<(), Box<dyn std::error::Error>> {
    let metadata = fs::metadata(path)?;

    let name = path.file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("?")
        .to_string();

    // Check if hidden and should be ignored
    if args.ignore_hidden && name.starts_with('.') {
        return Ok(());
    }

    let is_dir = metadata.is_dir();
    let file_size = if args.apparent_size {
        metadata.len()
    } else {
        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt;
            metadata.blocks() * 512
        }
        #[cfg(not(unix))]
        {
            metadata.len()
        }
    };

    all_files.push(FileNode {
        path: path.to_path_buf(),
        name,
        size: file_size,
        is_dir,
        depth,
    });

    // Recurse into directories
    if is_dir && (args.depth.is_none() || depth < args.depth.unwrap()) {
        if let Ok(entries) = fs::read_dir(path) {
            for entry in entries.flatten() {
                scan_recursive(&entry.path(), args, depth + 1, all_files)?;
            }
        }
    }

    Ok(())
}

pub fn aggregate_tree(mut nodes: Vec<FileNode>, args: &Args) -> Vec<FileNode> {
    // Build a map from path to all descendant sizes
    let mut descendant_sizes: HashMap<PathBuf, u64> = HashMap::new();

    // First pass: calculate total descendants for each directory
    for node in &nodes {
        if !node.is_dir {
            // For each file, add to all parent directories
            let mut current = node.path.clone();
            while let Some(parent) = current.parent() {
                *descendant_sizes.entry(parent.to_path_buf()).or_insert(0) += node.size;
                current = parent.to_path_buf();
            }
        }
    }

    // Second pass: update directory sizes with calculated values
    for node in &mut nodes {
        if node.is_dir {
            if let Some(&total) = descendant_sizes.get(&node.path) {
                node.size = total;
            }
        }
    }

    // Group by parent path
    let mut by_parent: HashMap<Option<PathBuf>, Vec<FileNode>> = HashMap::new();
    let mut root_dir: Option<FileNode> = None;

    for node in nodes {
        if node.depth == 0 && node.is_dir {
            root_dir = Some(node.clone());
        }

        let parent = node.path.parent().map(|p| p.to_path_buf());
        by_parent.entry(parent).or_insert_with(Vec::new).push(node);
    }

    // Sort each parent's children
    for children in by_parent.values_mut() {
        children.sort_by(|a, b| {
            if !args.reverse {
                a.size.cmp(&b.size)
            } else {
                b.size.cmp(&a.size)
            }
        });
    }

    // Flatten: collect all items grouped by parent
    let mut result = Vec::new();

    // Collect directories and files (excluding root)
    // Start from root's children
    let mut visited = std::collections::HashSet::new();
    if let Some(root_ref) = &root_dir {
        visit_children(root_ref, &by_parent, &mut result, &mut visited);
    }

    // Add root directory at the end
    if let Some(rd) = root_dir {
        result.push(rd);
    }

    // Filter by file/dir type
    if args.only_dir {
        result.retain(|n| n.is_dir);
    } else if args.only_file {
        result.retain(|n| !n.is_dir);
    }

    result
}

fn visit_children(dir: &FileNode, by_parent: &HashMap<Option<PathBuf>, Vec<FileNode>>, result: &mut Vec<FileNode>, visited: &mut std::collections::HashSet<PathBuf>) {
    let dir_key = Some(dir.path.clone());
    if let Some(children) = by_parent.get(&dir_key) {
