use crate::{Args, tree::FileNode};
use std::collections::HashMap;
use std::path::PathBuf;

pub struct TreeFormatter<'a> {
    args: &'a Args,
}

impl<'a> TreeFormatter<'a> {
    pub fn new(args: &'a Args) -> Self {
        TreeFormatter { args }
    }

    pub fn display(&self, nodes: &[FileNode], total_size: u64) {
        // Build parent -> child mapping to determine first/subsequent children
        let mut children_by_parent: HashMap<Option<PathBuf>, Vec<usize>> = HashMap::new();

        for (i, node) in nodes.iter().enumerate() {
            let parent = node.path.parent().map(|p| p.to_path_buf());
            children_by_parent.entry(parent).or_insert_with(Vec::new).push(i);
        }

        // Print each node
        for (i, node) in nodes.iter().enumerate() {
            let parent = node.path.parent().map(|p| p.to_path_buf());

            // Check if this is the first child of its parent
            let is_first_child = children_by_parent.get(&parent)
                .map(|indices| indices.len() > 0 && indices[0] == i)
                .unwrap_or(false);

            self.print_node(node, total_size, is_first_child && !node.is_dir);
        }

        // Print total line if not skipped
        if !self.args.skip_total && nodes.len() > 0 {
            self.print_total(total_size);
        }
    }

    fn print_node(&self, node: &FileNode, total_size: u64, is_first_child: bool) {
        let size_str = self.format_size(node.size);
        let percent = if total_size > 0 {
            (node.size as f64 / total_size as f64) * 100.0
        } else {
            0.0
        };

        let name = if self.args.full_paths {
            node.path.to_string_lossy().to_string()
        } else {
            node.name.clone()
        };

        // Determine the connector based on type and position
        let connector = if node.is_dir {
            "├─┴ "
        } else {
            match node.depth {
                0 => "┌─┴ ",
                1 => {
                    if is_first_child {
                        "│ ┌── "
                    } else {
                        "│ ├── "
                    }
                },
                2 => {
                    if is_first_child {
                        "│ ┌── "
                    } else {
                        "│ ├── "
                    }
                },
                _ => "│ ┌── ",
            }
        };

        if self.args.no_percent_bars {
            println!("{:>6}   {}{}", size_str, connector, name);
        } else {
            let bar = self.draw_bar(percent);
            let percent_str = format!("{:3}%", percent as i32);
            println!("{:>6}   {}{:<30} │{}│ {}", size_str, connector, name, bar, percent_str);
        }
    }

    fn print_total(&self, total_size: u64) {
        let size_str = self.format_size(total_size);
        println!("{:>6} ┌─┴", size_str);
    }

    fn format_size(&self, bytes: u64) -> String {
        match self.args.output_format.as_deref() {
            Some("si") => self.format_size_si(bytes),
            Some("b") => format!("{} B", bytes),
            Some("k") | Some("kib") => format!("{:.1} KiB", bytes as f64 / 1024.0),
            Some("m") | Some("mib") => format!("{:.1} MiB", bytes as f64 / (1024.0 * 1024.0)),
            Some("g") | Some("gib") => format!("{:.1} GiB", bytes as f64 / (1024.0 * 1024.0 * 1024.0)),
            Some("t") | Some("tib") => format!("{:.1} TiB", bytes as f64 / (1024.0 * 1024.0 * 1024.0 * 1024.0)),
            Some("kb") => format!("{:.1} KB", bytes as f64 / 1000.0),
            Some("mb") => format!("{:.1} MB", bytes as f64 / (1000.0 * 1000.0)),
            Some("gb") => format!("{:.1} GB", bytes as f64 / (1000.0 * 1000.0 * 1000.0)),
            Some("tb") => format!("{:.1} TB", bytes as f64 / (1000.0 * 1000.0 * 1000.0 * 1000.0)),
            _ => self.format_size_default(bytes),
        }
    }

    fn format_size_default(&self, bytes: u64) -> String {
        if bytes >= 1024 * 1024 * 1024 {
            format!("{:.1}G", bytes as f64 / (1024.0 * 1024.0 * 1024.0))
        } else if bytes >= 1024 * 1024 {
            format!("{:.1}M", bytes as f64 / (1024.0 * 1024.0))
        } else if bytes >= 1024 {
            format!("{:.1}K", bytes as f64 / 1024.0)
        } else {
            format!("{}B", bytes)
        }
    }

    fn format_size_si(&self, bytes: u64) -> String {
        if bytes >= 1000 * 1000 * 1000 {
            format!("{:.1}G", bytes as f64 / (1000.0 * 1000.0 * 1000.0))
        } else if bytes >= 1000 * 1000 {
            format!("{:.1}M", bytes as f64 / (1000.0 * 1000.0))
        } else if bytes >= 1000 {
            format!("{:.1}K", bytes as f64 / 1000.0)
        } else {
            format!("{}B", bytes)
        }
    }

    fn draw_bar(&self, percent: f64) -> String {
        let filled = (percent / 2.0) as usize;
        let empty = 50_usize.saturating_sub(filled);
        format!("{}{}",
            "█".repeat(filled),
            "░".repeat(empty)
        )
    }
}
